// Ambil semua baris dari Google Sheets
const items = $input.all();

// Rentang waktu: 7 hari lalu (00:00:00) sampai hari ini (23:59:59)
const today = new Date();
today.setHours(23, 59, 59, 999);
const sevenDaysAgo = new Date(today);
sevenDaysAgo.setDate(today.getDate() - 7);
sevenDaysAgo.setHours(0, 0, 0, 0);

// Ambil nilai kolom dengan beberapa kemungkinan nama header (tidak peka huruf besar/kecil)
const pick = (obj, names) => {
  const keys = Object.keys(obj);
  for (const n of names) {
    const k = keys.find((k) => k.trim().toLowerCase() === n);
    if (k !== undefined && obj[k] !== '' && obj[k] != null) return obj[k];
  }
  return '';
};

// Sheet memakai format DD/MM/YYYY -> harus di-parse manual agar tidak salah baca
const parseDate = (raw) => {
  const s = String(raw).trim();
  const m = s.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})/);
  if (m) {
    const [day, month, year] = [Number(m[1]), Number(m[2]), Number(m[3])];
    return new Date(year, month - 1, day);
  }
  const d = new Date(s); // cadangan: format ISO (YYYY-MM-DD)
  return isNaN(d.getTime()) ? null : d;
};

// Jumlah bisa berupa angka atau teks seperti "Rp 25.000"
const parseAmount = (raw) => {
  if (typeof raw === 'number') return raw;
  const digits = String(raw).replace(/[^0-9]/g, '');
  return digits ? Number(digits) : 0;
};

const rupiah = (n) => String(n).replace(/\B(?=(\d{3})+(?!\d))/g, '.');

// Filter 7 hari terakhir
const rows = [];
for (const item of items) {
  const rawDate = pick(item.json, ['tanggal', 'date', 'rawdate']);
  if (!rawDate) continue;
  const expenseDate = parseDate(rawDate);
  if (!expenseDate) continue;

  if (expenseDate >= sevenDaysAgo && expenseDate <= today) {
    rows.push({
      expenseDate,
      rawDate: String(rawDate),
      kategori: pick(item.json, ['kategori', 'category']) || '-',
      deskripsi: pick(item.json, ['deskripsi', 'keterangan', 'description']) || '-',
      metode: pick(item.json, ['metode', 'metode pembayaran', 'payment method', 'method']) || '-',
      penerima: pick(item.json, ['penerima', 'merchant', 'toko']) || '-',
      jumlah: parseAmount(pick(item.json, ['jumlah', 'nominal', 'amount', 'total'])),
    });
  }
}
rows.sort((a, b) => a.expenseDate - b.expenseDate);

// Format teks untuk AI
let formattedString = '📊 Data pengeluaran saya 7 hari terakhir:\n';
let total = 0;
for (const r of rows) {
  total += r.jumlah;
  formattedString +=
    ` - ${r.rawDate} | ${r.kategori}\n` +
    `   ${r.deskripsi}\n` +
    `   Metode: ${r.metode}\n` +
    `   Penerima: ${r.penerima}\n` +
    `   💸 Rp${rupiah(r.jumlah)}\n\n`;
}
formattedString += `Total: Rp${rupiah(total)} (${rows.length} transaksi)`;

const hasExpenses = rows.length > 0;

return [{
  json: {
    hasExpenses,
    count: rows.length,
    total,
    totalFormatted: rupiah(total),
    promptData: hasExpenses ? formattedString : '',
  },
}];

